macro_rules! bash_program {
    () => {
        # [doc = " Get the path attempted as a `bash` interpreter, for fixture scripts having no `#!` we can use."] # [doc = ""] # [doc = " This is rarely called on Unix-like systems, provided that fixture scripts have usable shebang"] # [doc = " (`#!`) lines and are marked executable. However, Windows does not recognize `#!` when executing"] # [doc = " a file. If all fixture scripts that cannot be directly executed are `bash` scripts or can be"] # [doc = " treated as such, fixture generation still works on Windows, as long as this function manages to"] # [doc = " find or guess a suitable `bash` interpreter."] # [doc = ""] # [doc = " ### Search order"] # [doc = ""] # [doc = " This function is used internally. It is public to facilitate diagnostic use. The following"] # [doc = " details are subject to change without warning, and changes are treated as non-breaking."] # [doc = ""] # [doc = " The `bash.exe` found in a path search is not always suitable on Windows. This is mainly because"] # [doc = " `bash.exe` in `System32`, which is associated with WSL, would often be found first. But even"] # [doc = " where that is not the case, the best `bash.exe` to use to run fixture scripts to set up Git"] # [doc = " repositories for testing is usually one associated with Git for Windows, even if some other"] # [doc = " `bash.exe` would be found in a path search. Currently, the search order we use is as follows:"] # [doc = ""] # [doc = " 1. The shim `bash.exe`, which sets environment variables when run and is, on some systems,"] # [doc = "    needed to find the POSIX utilities that scripts need (or correct versions of them)."] # [doc = ""] # [doc = " 2. The non-shim `bash.exe`, which is sometimes available even when the shim is not available."] # [doc = "    This is mainly because the Git for Windows SDK does not come with a `bash.exe` shim."] # [doc = ""] # [doc = " 3. As a fallback, the simple name `bash.exe`, which triggers a path search when run."] # [doc = ""] # [doc = " On non-Windows systems, the simple name `bash` is used, which triggers a path search when run."] pub fn bash_program () -> & 'static Path { static GIT_BASH : LazyLock < PathBuf > = LazyLock :: new (| | { if cfg ! (windows) { GIT_CORE_DIR . ancestors () . nth (3) . map (OsStr :: new) . iter () . flat_map (| prefix | { ["/bin/bash.exe" , "/usr/bin/bash.exe"] . into_iter () . map (| suffix | { let mut raw_path = (* prefix) . to_owned () ; raw_path . push (suffix) ; raw_path }) }) . map (PathBuf :: from) . find (| bash | bash . is_file ()) . unwrap_or_else (| | "bash.exe" . into ()) } else { "bash" . into () } }) ; GIT_BASH . as_ref () }
    };
}

bash_program!();